ALTER TABLE public.jobs ADD COLUMN merged_into_job_id uuid REFERENCES public.jobs(id);
CREATE TABLE public.job_merge_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,actor_id uuid NOT NULL,job_ids uuid[] NOT NULL,keep_id uuid NOT NULL,fingerprint text NOT NULL,preview jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz);
GRANT SELECT ON public.job_merge_previews TO authenticated; GRANT ALL ON public.job_merge_previews TO service_role;
ALTER TABLE public.job_merge_previews ENABLE ROW LEVEL SECURITY;
CREATE POLICY job_merge_previews_admin ON public.job_merge_previews FOR SELECT TO authenticated USING(org_id=public.get_user_org_id() AND public.has_role_in_org(auth.uid(),org_id,'admin'));
CREATE FUNCTION public.job_merge_snapshot(_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record; result jsonb; content jsonb; BEGIN SELECT jsonb_agg(to_jsonb(j) ORDER BY j.id) INTO result FROM jobs j WHERE j.id=ANY(_ids); result:=jsonb_build_object('jobs',result,'links','{}'::jsonb); FOR t IN SELECT c.table_name,c.column_name FROM information_schema.columns c JOIN information_schema.tables tb ON tb.table_schema=c.table_schema AND tb.table_name=c.table_name AND tb.table_type='BASE TABLE' WHERE c.table_schema='public' AND c.data_type='uuid' AND c.column_name IN ('job_id','last_job_id','next_job_id','created_job_id','converted_job_id','remedial_job_id','related_job_id','linked_job_id','moved_to_job_id') AND c.table_name NOT IN ('job_merge_previews') ORDER BY c.table_name,c.column_name LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb) FROM public.%I x WHERE %I=ANY($1)',t.table_name,t.column_name) INTO content USING _ids; result:=jsonb_set(result,ARRAY['links',t.table_name||'.'||t.column_name],content); END LOOP; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.job_merge_snapshot(uuid[]) FROM PUBLIC;
CREATE FUNCTION public.preview_job_merge(_job_ids uuid[],_keep_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=get_user_org_id(); snap jsonb; token uuid; n integer; BEGIN IF o IS NULL OR NOT has_role_in_org(auth.uid(),o,'admin') THEN RAISE EXCEPTION 'Office access required'; END IF; SELECT count(DISTINCT x) INTO n FROM unnest(_job_ids)x; IF n<2 OR n<>cardinality(_job_ids) OR NOT _keep_id=ANY(_job_ids) THEN RAISE EXCEPTION 'Choose at least two distinct jobs and a kept job'; END IF; IF (SELECT count(*) FROM jobs WHERE id=ANY(_job_ids) AND org_id=o AND merged_into_job_id IS NULL AND status NOT IN ('archived','cancelled'))<>n THEN RAISE EXCEPTION 'Choose active jobs in your company'; END IF; IF (SELECT count(DISTINCT site_id) FROM jobs WHERE id=ANY(_job_ids))<>1 OR EXISTS(SELECT 1 FROM jobs WHERE id=ANY(_job_ids) AND site_id IS NULL) THEN RAISE EXCEPTION 'Jobs must belong to the same site'; END IF; snap:=job_merge_snapshot(_job_ids); INSERT INTO job_merge_previews(org_id,actor_id,job_ids,keep_id,fingerprint,preview) VALUES(o,auth.uid(),_job_ids,_keep_id,md5(snap::text),snap) RETURNING id INTO token; RETURN jsonb_build_object('token',token,'jobs',snap->'jobs','counts',(SELECT jsonb_object_agg(key,jsonb_array_length(value)) FROM jsonb_each(snap->'links'))); END $$;
CREATE FUNCTION public.confirm_job_merge(_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=get_user_org_id(); p job_merge_previews%ROWTYPE; src uuid[]; t record; refs text; BEGIN IF o IS NULL OR NOT has_role_in_org(auth.uid(),o,'admin') THEN RAISE EXCEPTION 'Office access required'; END IF; SELECT * INTO p FROM job_merge_previews WHERE id=_token AND org_id=o AND actor_id=auth.uid() AND confirmed_at IS NULL AND created_at>now()-interval '10 minutes' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Preview expired. Preview again.'; END IF; PERFORM 1 FROM jobs WHERE id=ANY(p.job_ids) ORDER BY id FOR UPDATE; IF EXISTS(SELECT 1 FROM jobs WHERE id=ANY(p.job_ids) AND (org_id<>o OR merged_into_job_id IS NOT NULL)) OR md5(job_merge_snapshot(p.job_ids)::text)<>p.fingerprint THEN RAISE EXCEPTION 'Jobs changed since preview. Preview again.'; END IF; src:=array_remove(p.job_ids,p.keep_id); SELECT string_agg(reference_number,', ' ORDER BY reference_number) INTO refs FROM jobs WHERE id=ANY(src);
INSERT INTO job_risers(org_id,job_id,asset_id,selected) SELECT o,p.keep_id,asset_id,bool_or(selected) FROM job_risers WHERE job_id=ANY(p.job_ids) GROUP BY asset_id ON CONFLICT(job_id,asset_id) DO UPDATE SET selected=job_risers.selected OR EXCLUDED.selected;
DELETE FROM job_risers WHERE job_id=ANY(src);
FOR t IN SELECT c.table_name,c.column_name FROM information_schema.columns c JOIN information_schema.tables tb ON tb.table_schema=c.table_schema AND tb.table_name=c.table_name AND tb.table_type='BASE TABLE' WHERE c.table_schema='public' AND c.data_type='uuid' AND c.column_name IN ('job_id','last_job_id','next_job_id','created_job_id','converted_job_id','remedial_job_id','related_job_id','linked_job_id','moved_to_job_id') AND c.table_name NOT IN ('job_risers','job_merge_previews') ORDER BY c.table_name,c.column_name LOOP EXECUTE format('UPDATE public.%I SET %I=$1 WHERE %I=ANY($2)',t.table_name,t.column_name,t.column_name) USING p.keep_id,src; END LOOP;
UPDATE jobs SET status='archived',merged_into_job_id=p.keep_id WHERE id=ANY(src) AND org_id=o;
INSERT INTO job_activity_log(job_id,user_id,org_id,action,details) VALUES(p.keep_id,auth.uid(),o,'jobs_merged','Merged and archived '||refs||'. Original records preserved in merge preview '||p.id::text);
UPDATE job_merge_previews SET confirmed_at=now() WHERE id=p.id; RETURN p.keep_id;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'Merge blocked: conflicting assignments, schedules or template locks. Nothing was moved. Review these records before merging.'; END $$;
REVOKE ALL ON FUNCTION public.preview_job_merge(uuid[],uuid),public.confirm_job_merge(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.preview_job_merge(uuid[],uuid),public.confirm_job_merge(uuid) TO authenticated;